import React from "react";

function RoleSelection({ user, logout }) {
  const roles = ["Students", "Professionals", "Homemakers", "Customize Role"];

  return (
    <div className="flex flex-col items-center justify-center h-screen bg-gradient-to-r from-green-400 via-blue-500 to-purple-600">
      <h1 className="text-3xl font-bold text-white mb-6">Welcome, {user.username} 🎉</h1>
      <div className="grid grid-cols-2 gap-4">
        {roles.map((role, i) => (
          <button key={i} className="bg-white text-purple-600 font-semibold px-6 py-4 rounded-2xl shadow-lg hover:bg-purple-200">
            {role}
          </button>
        ))}
      </div>
      <button onClick={logout} className="mt-6 bg-red-500 px-6 py-2 text-white rounded-lg hover:bg-red-700">
        Logout
      </button>
    </div>
  );
}

export default RoleSelection;
